	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void partialDictionaryBatchFailurePreservesRecoveryAndReopen(boolean capacityFailure, @TempDir Path directory)
			throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,ospc,psoc,posc")
				.setBulkOperationSize(256)
				.setValueDBSize(32L << 20)
				.setTripleDBSize(32L << 20);
		Model expected = new LinkedHashModel();
		IRI datatype = Values.iri("urn:batch:fault:datatype");
		Value first = Values.literal("x".repeat(700) + "plumless", datatype);
		Value second = Values.literal("x".repeat(700) + "buckeroo", datatype);
		assertEquals(lexicalHash(first), lexicalHash(second));
		for (int i = 0; i < 600; i++) {
			Value object = switch (i % 4) {
			case 0 -> first;
			case 1 -> second;
			case 2 -> Values.literal("long-batch-object-" + "y".repeat(40) + i, "nb");
			default -> Values.tripleTerm(Values.iri("urn:batch:fault:nested-" + "z".repeat(40) + i),
					RDF.TYPE, Values.tripleTerm(Values.iri("urn:batch:fault:inner"), RDF.TYPE, first));
			};
			expected.add(Values.iri("urn:batch:fault:subject-" + "s".repeat(40) + i), RDF.TYPE, object,
					Values.iri("urn:batch:fault:context:" + i % 3));
		}
		FailingBatchLmdbStore store = new FailingBatchLmdbStore(directory.toFile(), config, capacityFailure);
		SailRepository repository = new SailRepository(store);
		try {
			repository.init();
			long initialMap = store.values.mapSizeBytes();
			try (RepositoryConnection connection = repository.getConnection()) {
				connection.begin(IsolationLevels.NONE);
				store.values.arm();
				if (capacityFailure) {
					connection.add(expected);
					connection.commit();
					assertTrue(store.values.mapSizeBytes() > initialMap, "native MAP_FULL forces dictionary growth");
				} else {
					RepositoryException thrown = assertThrows(RepositoryException.class,
							() -> connection.add(expected));
					Throwable cause = thrown;
					while (cause.getCause() != null && cause != store.values.injectedFailure) {
						cause = cause.getCause();
					}
					assertSame(store.values.injectedFailure, cause, "the original partial-write failure survives");
					connection.rollback();
					assertEquals(0, connection.size(), "the first unsubmitted dictionary batch publishes no triples");
					connection.begin(IsolationLevels.NONE);
					connection.add(expected);
					connection.commit();
				}
				assertEquals(1, store.values.failures,
						"the fault reaches a real partial dictionary batch exactly once");
				verifyRepositoryRows(connection, expected);
			}
		} finally {
			repository.shutDown();
		}
		SailRepository reopened = new SailRepository(new LmdbStore(directory.toFile(), config));
		try {
			reopened.init();
			try (RepositoryConnection connection = reopened.getConnection()) {
				verifyRepositoryRows(connection, expected);
			}
		} finally {
			reopened.shutDown();
		}
	}

	private static void verifyRepositoryRows(RepositoryConnection connection, Model expected) {
		Model actual = new LinkedHashModel();
		try (RepositoryResult<Statement> rows = connection.getStatements(null, null, null, false)) {
			while (rows.hasNext()) {
				assertTrue(actual.add(rows.next()), "no duplicate complete rows");
			}
		}
		assertEquals(expected, actual, "every lexical value, nested dependency, collision and context survives");
		assertEquals(expected.size(), connection.size());
	}

	private static final class FailingBatchLmdbStore extends LmdbStore {
		private final boolean capacityFailure;
		private FailingBatchValueStore values;

		private FailingBatchLmdbStore(File directory, LmdbStoreConfig config, boolean capacityFailure) {
			super(directory, config);
			this.capacityFailure = capacityFailure;
		}

		@Override
		LmdbSailStore createBackingStore(File directory, StoreProperties properties, LmdbStoreConfig config,
				boolean sketchEnabled) throws IOException {
			return new LmdbSailStore(directory, properties, config, sketchEnabled,
					(valueDir, storeProperties, settings) -> {
						values = new FailingBatchValueStore(valueDir, storeProperties, settings, capacityFailure);
						return values;
					}, TripleStore::new);
		}
	}

	private static final class FailingBatchValueStore extends ValueStore {
		private final boolean capacityFailure;
		private final IOException injectedFailure = new IOException("injected dictionary batch failure");
		private int writesBeforeFailure;
		private int failures;

		private FailingBatchValueStore(File directory, StoreProperties properties, LmdbStoreConfig config,
				boolean capacityFailure) throws IOException {
			super(directory, properties, config);
			this.capacityFailure = capacityFailure;
		}

		private void arm() {
			writesBeforeFailure = 19;
		}

		@Override
		<T> T writeTransaction(LmdbUtil.Transaction<T> transaction) throws IOException {
			return super.writeTransaction((stack, txn) -> {
				T result = transaction.exec(stack, txn);
				if (writesBeforeFailure > 0 && StackWalker.getInstance()
						.walk(frames -> frames.anyMatch(frame -> frame.getClassName().equals(ValueStore.class.getName())
								&& frame.getMethodName().equals("findIds")))
						&& --writesBeforeFailure == 0) {
					failures++;
					if (capacityFailure) {
						LmdbUtil.E(MDB_MAP_FULL);
					}
					throw injectedFailure;
				}
				return result;
			});
		}
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void boundedValueBatchPreservesMixedIdentitiesAndCollisions(boolean checkpoint, @TempDir Path directory)
			throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig().setValueDBSize(32L << 20);
		File localDirectory = directory.resolve("local").toFile();
		Value[] expected;
		long[] resolved;
		try (ReadTrackingValueStore local = new ReadTrackingValueStore(localDirectory, config);
				ReadTrackingValueStore foreign = new ReadTrackingValueStore(directory.resolve("foreign").toFile(),
						config)) {
			LmdbIRI own = local.createIRI("urn:batch:original");
			local.startTransaction(false);
			long originalId = local.storeValue(own);
			local.commit();
			own.setNamespaceAndIri("urn:batch:", "changed");
			LmdbIRI other = foreign.createIRI("urn:foreign:lexical-value");
			foreign.startTransaction(false);
			foreign.storeValue(other);
			foreign.commit();
			IRI datatype = Values.iri("urn:batch:datatype");
			Value collisionFirst = Values.literal("x".repeat(700) + "plumless", datatype);
			Value collisionSecond = Values.literal("x".repeat(700) + "buckeroo", datatype);
			assertEquals(collisionFirst.stringValue().length(), collisionSecond.stringValue().length());
			assertEquals(lexicalHash(collisionFirst), lexicalHash(collisionSecond),
					"equal-length lexical CRC32 collisions survive their common dictionary encoding prefix");
			expected = new Value[] { own, other, Values.bnode("batch-node"), Values.literal("language", "nb"),
					Values.literal(42), Values.literal("typed", datatype),
					Values.tripleTerm(Values.iri("urn:batch:quoted"), RDF.TYPE,
							Values.tripleTerm(other, RDF.TYPE, Values.literal("nested"))),
					collisionFirst, collisionSecond, collisionFirst };
			Value[] input = Arrays.copyOf(expected, expected.length + 13);
			resolved = new long[input.length];
			Arrays.fill(resolved, Long.MIN_VALUE);
			local.startTransaction(false);
			if (checkpoint) {
				local.setReplayDecision(new TxnReplayPolicy.Decision(new TxnReplayPolicy(), true, false, 0, 0, 0)
						.forNativeCheckpoints());
			}
			local.storeValues(input, resolved, expected.length);
			assertEquals(checkpoint, local.batchReadAdmissions > 0, "the selected native bulk path must execute");
			assertNotEquals(originalId, resolved[0], "a mutated own value must not reuse its stale lexical ID");
			assertNotEquals(resolved[7], resolved[8], "colliding large values remain distinct");
			assertEquals(resolved[7], resolved[9], "the duplicate large value resolves to its original ID");
			for (int i = expected.length; i < resolved.length; i++) {
				assertEquals(Long.MIN_VALUE, resolved[i], "invalid tail capacity is never visited");
			}
			for (int i = 0; i < expected.length; i++) {
				assertNotEquals(LmdbValue.UNKNOWN_ID, resolved[i]);
				assertEquals(expected[i], local.getValue(resolved[i]));
			}
			local.commit();
			assertEquals(Values.iri("urn:batch:original"), local.getValue(originalId));
		}
		try (ReadTrackingValueStore reopened = new ReadTrackingValueStore(localDirectory, config)) {
			for (int i = 0; i < expected.length; i++) {
				assertEquals(resolved[i], reopened.getId(expected[i]));
				assertEquals(expected[i], reopened.getValue(resolved[i]));
			}
		}
	}

	@ParameterizedTest
	@ValueSource(longs = { 524_288L, 67_108_864L })
	void shuffledPrimaryWritesPreserveDuplicateCallbacksAndPromotionReplay(long mapBytes,
			@TempDir Path directory) throws Exception {
		int unique = 12_000;
		int count = unique * 2;
		long[] subjects = new long[count + 17];
		long[] predicates = new long[count + 17];
		long[] objects = new long[count + 17];
		long[] contexts = new long[count + 17];
		Map<Long, long[]> expected = new HashMap<>();
		for (int i = 0; i < count; i++) {
			int logical = i % unique;
			subjects[i] = 100_000L + logical * 7_919L % unique;
			predicates[i] = 1L + logical % 31;
			objects[i] = 200_000L + logical;
			contexts[i] = 1_000L + logical % 5;
			expected.put(subjects[i], new long[] { subjects[i], predicates[i], objects[i], contexts[i] });
		}
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,ospc,psoc").setTripleDBSize(mapBytes).setAutoGrow(true);
		try (TripleStore store = new TripleStore(directory.toFile(), config, null)) {
			store.startTransaction();
			store.storeTriplesAligned(subjects, predicates, objects, contexts, count, false);
			store.commit();
			long beforePromotion = mapSize(store);
			List<Integer> callbacks = new ArrayList<>();
			store.startTransaction();
			store.storeTriplesAligned(subjects, predicates, objects, contexts, count, true, callbacks::add);
			store.commit();
			assertEquals(IntStream.range(0, unique).boxed().toList(), callbacks,
					"first occurrences produce exactly one callback in original input order");
			if (mapBytes == 524_288L) {
				assertTrue(mapSize(store) > beforePromotion, "promotion must exercise actual capacity replay");
			}
			verifyRows(store, expected);
		}
		try (TripleStore reopened = new TripleStore(directory.toFile(), config, null)) {
			verifyRows(reopened, expected);
		}
	}

	private static void verifyRows(TripleStore store, Map<Long, long[]> expected) throws IOException {
		try (Txn txn = store.getTxnManager().createReadTxn()) {
			verifyPattern(store, txn, expected, -1, -1);
			for (long predicate = 1; predicate <= 31; predicate++) {
				verifyPattern(store, txn, expected, predicate, -1);
			}
			for (long context = 1_000; context < 1_005; context++) {
				verifyPattern(store, txn, expected, -1, context);
			}
			for (long[] expectedRow : expected.values()) {
				try (RecordIterator rows = store.getTriples(txn, -1, -1, expectedRow[2], -1, true)) {
					assertArrayEquals(expectedRow, rows.next(), "object-bound scan selects OSPC");
					assertEquals(null, rows.next(), "one exact row per object");
				}
				try (RecordIterator inferred = store.getTriples(txn, -1, -1, expectedRow[2], -1, false)) {
					assertEquals(null, inferred.next(), "secondary inferred rows are removed on promotion");
				}
			}
			try (RecordIterator inferred = store.getTriples(txn, -1, -1, -1, -1, false)) {
				assertEquals(null, inferred.next(), "promotion removes all inferred rows");
			}
		}
	}

	private static void verifyPattern(TripleStore store, Txn txn, Map<Long, long[]> expected, long predicate,
			long context) throws IOException {
		Map<Long, long[]> remaining = new HashMap<>();
		for (long[] row : expected.values()) {
			if ((predicate < 0 || row[1] == predicate) && (context < 0 || row[3] == context)) {
				remaining.put(row[0], row);
			}
		}
		try (RecordIterator rows = store.getTriples(txn, -1, predicate, -1, context, true)) {
			long[] row;
			while ((row = rows.next()) != null) {
				assertArrayEquals(remaining.remove(row[0]), row, "exact selected primary/PSOC/context contents");
			}
		}
		assertTrue(remaining.isEmpty(), "complete selected cardinality");
		try (RecordIterator inferred = store.getTriples(txn, -1, predicate, -1, context, false)) {
			assertEquals(null, inferred.next(), "selected inferred rows are removed on promotion");
		}
	}

	private static long lexicalHash(Value value) {
		CRC32 checksum = new CRC32();
		checksum.update(value.stringValue().getBytes(StandardCharsets.UTF_8));
		return checksum.getValue();
	}

	private static long mapSize(TripleStore store) {
		try (MemoryStack stack = MemoryStack.stackPush()) {
			MDBEnvInfo info = MDBEnvInfo.malloc(stack);
			assertEquals(MDB_SUCCESS, mdb_env_info(store.env, info));
			return info.me_mapsize();
		}
	}

	private static final class ReadTrackingValueStore extends ValueStore implements AutoCloseable {
		private int batchReadAdmissions;

		private ReadTrackingValueStore(File directory, LmdbStoreConfig config) throws IOException {
			super(directory, config);
		}

		@Override
		<T> T readTransaction(long environment, LmdbUtil.Transaction<T> transaction) throws IOException {
			if (StackWalker.getInstance()
					.walk(frames -> frames.anyMatch(frame -> frame.getClassName().equals(ValueStore.class.getName())
							&& frame.getMethodName().equals("findIds")))) {
				batchReadAdmissions++;
			}
			return super.readTransaction(environment, transaction);
		}
	}
